import type { Challenge, LevelDef, Landmass, MaterialId, Vec2, VehicleId } from '../types';

/**
 * Level data. Terrain is described by landmasses (top-surface polylines). World units are
 * metres, +y is up, the gap starts at x = 0. All geometry is generated by `make()` from a
 * compact description so levels stay readable; budgets are tuned against the reference
 * solutions in solutions.ts (verified by tests/levels.test.ts).
 */
interface Pillar { x: number; w: number; y?: number }
interface Spec {
  id: number; name: string; tier: 1 | 2 | 3 | 4 | 5 | 6; hint: string;
  vehicle: VehicleId; materials: MaterialId[];
  W: number; yl?: number; yr?: number; pillars?: Pillar[];
  depths?: number[]; aerial?: Vec2[];
  budget: number; gold: number; challenge: Challenge;
}

const ALL: MaterialId[] = ['road', 'wood', 'steel', 'cable'];

function make(s: Spec): LevelDef {
  const yl = s.yl ?? 0, yr = s.yr ?? 0, W = s.W;
  const depths = s.depths ?? [3, 6];
  const left: Landmass = { top: [{ x: -22, y: yl + 1.4 }, { x: -14, y: yl + 0.4 }, { x: -9, y: yl }, { x: 0, y: yl }] };
  const right: Landmass = { top: [{ x: W, y: yr }, { x: W + 8, y: yr }, { x: W + 13, y: yr + 0.4 }, { x: W + 20, y: yr + 1.4 }] };
  const landmasses: Landmass[] = [left];
  const anchors: Vec2[] = [];
  const edge = (x: number, y: number) => {
    anchors.push({ x, y });
    for (const d of depths) anchors.push({ x, y: y - d });
  };
  edge(0, yl);
  const lerpY = (x: number) => yl + (yr - yl) * (x / W);
  for (const p of s.pillars ?? []) {
    const py = Math.round((p.y ?? lerpY(p.x)) * 2) / 2;
    landmasses.push({ top: [{ x: p.x - p.w / 2, y: py }, { x: p.x + p.w / 2, y: py }] });
    edge(p.x - p.w / 2, py);
    edge(p.x + p.w / 2, py);
  }
  landmasses.push(right);
  edge(W, yr);
  for (const a of s.aerial ?? []) anchors.push(a);
  const ys = [yl, yr, ...(s.pillars ?? []).map((p) => p.y ?? lerpY(p.x)), ...(s.aerial ?? []).map((a) => a.y)];
  return {
    id: s.id, name: s.name, tier: s.tier, hint: s.hint,
    landmasses, anchors,
    buildArea: { minX: -1.5, maxX: W + 1.5, minY: Math.min(yl, yr) - Math.max(8.5, Math.max(...depths) + 1.5), maxY: Math.max(...ys) + 4 },
    startX: -4.5, goalX: W + 6,
    budget: s.budget, goldBudget: s.gold, materials: s.materials, vehicle: s.vehicle, challenge: s.challenge,
  };
}

const safety = (ratio: number): Challenge => ({ type: 'safety', ratio, text: `Keep every member below ${Math.round(ratio * 100)}% of its strength` });
const beams = (n: number): Challenge => ({ type: 'maxBeams', value: n, text: `Use at most ${n} beams` });
const noMat = (m: MaterialId, label: string): Challenge => ({ type: 'noMaterial', material: m, text: `Finish without using ${label}` });

